mapper.select:
select

  distinct


from safety_build_depart_confirm




  order by ${orderByClause}



    limit ${offset}, ${limit}


    limit ${limit}

select sdcl.id,sdcl.EMPLOYEE_CODE,sdcl.EMPLOYEE_NAME,sdcl.OLD_DEPT_CODE, sdcl.OLD_DEPT_NAME,sdcl.NEW_DEPT_CODE,sdcl.NEW_DEPT_NAME,sdcl.UPDATE_TIME, sdcl.DUTY_DEPT_CODE,sdcl.DUTY_DEPT_NAME,sdcl.DUTY_EMP_CODE,sdcl.DUTY_EMP_NAME, case when sbwl.UPDATE_TIME is null then '否' else '是' end is_white, sbwl.CREATE_USER_CODE ,sbwl.CREATE_USER_NAME,sbwl.CREATE_USER_ROLE,sbwl.CREATE_REASON, sbwl.UPDATE_TIME white_update_time,BUILD_CONFIRM_FLAG as confirm_Flag, sdcl.create_time, sdcl.OLD_DUTY_EMP_CODE, sdcl.OLD_DUTY_EMP_NAME from safety.safety_build_depart_change sdcl left join safety.safety_build_white_list sbwl on sdcl.EMPLOYEE_CODE = sbwl.EMPLOYEE_CODE and sbwl.IS_DELETE = 0 where 1 = 1 and (BUILD_CONFIRM_FLAG='0' or (WHITE_CONFIRM_FLAG='0' and sbwl.UPDATE_TIME is not null))
order by ${orderByClause}
limit ${offset}, ${limit}
limit ${limit}
